import unittest

from roomclash.rooms import Booking, clashes, find_conflicts


class BasicTests(unittest.TestCase):
    def test_overlap(self):
        a = Booking("Aurora", 600, 660, "ann", 4)
        b = Booking("Aurora", 630, 700, "bob", 4)
